theorem CycleBridgePath.complementary_arcs_length_add
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {s : V}
    {cycle : G.Walk s s}
    (bridge : CycleBridgePath G cycle)
    {p : G.Path bridge.left bridge.right}
    {q : G.Path bridge.right bridge.left}
    (hdecomp :
      (p : G.Walk bridge.left bridge.right).append
          (q : G.Walk bridge.right bridge.left) =
        cycle.rotate bridge.left bridge.left_mem_cycle) :
    (p : G.Walk bridge.left bridge.right).length +
        (q : G.Walk bridge.right bridge.left).length =
      cycle.length

theorem CycleBridgePath.tails_disjoint_of_arc_support_subset
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {s : V}
    {cycle : G.Walk s s}
    (bridge : CycleBridgePath G cycle)
    {arc : G.Walk bridge.left bridge.right}
    (arc_isPath : arc.IsPath)
    (arc_support_subset : arc.support ⊆ cycle.support) :
    bridge.path.support.tail.Disjoint arc.reverse.support.tail

theorem CycleCertificate.hasPowerOfTwoCycle {V : Type u}
    {G : SimpleGraph V} (certificate : CycleCertificate G) :
    HasPowerOfTwoCycle G

theorem hasPowerOfTwoCycle_of_witness {V : Type u} {G : SimpleGraph V}
    {k : ℕ} {v : V} (c : G.Walk v v) (hk : k ≥ 2)
    (hc : c.IsCycle) (hlen : c.length = 2^k) : HasPowerOfTwoCycle G

theorem attachmentSet_two_or_singleton
    {C K : Finset V}
    (hattach : (attachmentSet G C K).Nonempty) :
    (∃ a b, a ∈ attachmentSet G C K ∧
      b ∈ attachmentSet G C K ∧ a ≠ b) ∨
    ∃ r, attachmentSet G C K = {r}

theorem rootedDouble_projection_length
    {V : Type u} {G : SimpleGraph V} {r : V}
    {x y : RootedDoubleVertex V r}
    (p : (rootedDoubleGraph G r).Walk x y) :
    (p.map rootedDoubleProjectionHom).length = p.length

theorem rootedDouble_cycle_common_tag
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {r : V}
    {x : RootedDoubleVertex V r}
    (p : (rootedDoubleGraph G r).Walk x x) (hp : p.IsCycle) :
    ∃ b : Bool, ∀ z, z ∈ p.support → z ≠ none →
      ∃ v : {v : V // v ≠ r}, z = some (b, v)

theorem rootedDouble_cycle_projection
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {r : V}
    {x : RootedDoubleVertex V r}
    (p : (rootedDoubleGraph G r).Walk x x) (hp : p.IsCycle) :
    (p.map rootedDoubleProjectionHom).IsCycle ∧
      (p.map rootedDoubleProjectionHom).length = p.length

theorem rootedDouble_cycle_projection_injOn
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {r : V}
    {x : RootedDoubleVertex V r}
    (p : (rootedDoubleGraph G r).Walk x x) (hp : p.IsCycle) :
    Set.InjOn rootedDoubleProjection {z | z ∈ p.support}

theorem quotient_root_degree [DecidableEq V] [Fintype V] [DecidableRel G.Adj] :
    (terminalQuotientGraph G a b).degree none =
      Fintype.card {v : V // v ≠ a ∧ v ≠ b ∧ (G.Adj a v ∨ G.Adj b v)}

theorem SimpleGraph.Walk.IsPath.support_subset_of_boundary_avoiding_root
    {V : Type u} {G : SimpleGraph V}
    {D : Finset V} {r u v : V} {p : G.Walk u v}
    (hp : p.IsPath) (hstart : u ∈ D) (hroot : r ∉ p.support)
    (hboundary : ∀ a, a ∈ D → ∀ b, b ∉ D → G.Adj a b → b = r) :
    ∀ z, z ∈ p.support → z ∈ D

theorem ExternalReachable.refl
    {V : Type u} {G : SimpleGraph V} {s : V} {C : G.Walk s s}
    {x : V} (hx : x ∉ C.support) : ExternalReachable G C x x

theorem rootedDouble_cycle_localization
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {r : V}
    {x : RootedDoubleVertex V r}
    (p : (rootedDoubleGraph G r).Walk x x) (hp : p.IsCycle) :
    ∃ b : Bool, ∀ z, z ∈ p.support →
      z = none ∨ ∃ v : {v : V // v ≠ r}, z = some (b, v)

theorem rootedDouble_cycle_localization_projection
    {V : Type u} {G : SimpleGraph V} [DecidableEq V] {r : V}
    {x : RootedDoubleVertex V r}
    (p : (rootedDoubleGraph G r).Walk x x) (hp : p.IsCycle) :
    (p.map rootedDoubleProjectionHom).IsCycle ∧
      (p.map rootedDoubleProjectionHom).length = p.length

theorem EdgeMinimalCounterexample.high_degree_incidence_le_cubic_plus_connectors
    {V : Type u} {G : SimpleGraph V}
    [Fintype V] [DecidableEq V] [DecidableRel G.Adj]
    (M : EdgeMinimalCounterexample G) :
    let H := Finset.univ.filter (fun v => 4 ≤ G.degree v)
    let L := Finset.univ.filter (fun v => G.degree v = 3)
    4 * H.card ≤ L.card +
      (L.filter (fun v => (H.filter (G.Adj v)).card = 2)).card

theorem EdgeMinimalCounterexample.highDegreeAuxGraph_connector_unique
    (M : EdgeMinimalCounterexample G) {x y : HighDegreeVertex G}
    (hxy : x ≠ y) {v w : V}
    (hvx : G.Adj v x.1) (hvy : G.Adj v y.1)
    (hwx : G.Adj w x.1) (hwy : G.Adj w y.1) : v = w

theorem exteriorComponentCarrier_not_mem_hull (H : PentagramEarHull G)
    [Fintype V] (C : H.exteriorGraph.ConnectedComponent) {v : V}
    (hv : v ∈ H.exteriorComponentCarrier C) : v ∉ H.hull

theorem exists_rotated_connector (H : PentagramEarHull G) {i j : Fin 5}
    (K : Connector H i j) :
    ∃ d : Fin 5, d ≠ 0 ∧ Nonempty (Connector (rotateHull H i) 0 d)

theorem CubicTwoTerminalCompletion.terminal_length_equation
    {V : Type u} {G : SimpleGraph V}
    [Fintype V] [DecidableRel G.Adj]
    (T : CubicTwoTerminalCompletion G) {k : ℕ}
    (hdyadic : (T.gadget.append T.returnPath.reverse).length = 2 ^ k) :
    T.gadget.length + T.returnPath.length = 2 ^ k
